import { createHash } from "node:crypto"
import fs from "node:fs"
import path from "node:path"

import type { LinkMode } from "../../../../lib/link/config.ts"
import { readRecordedMode } from "../../../../lib/link/settings_json.ts"
import * as env from "../../../lib/measurekit/env.ts"
import { expandHome, firstLine, isFile, isSymlink, readUtf8, resolveLinks } from "../../../lib/measurekit/files.ts"
import { isJsonObject, parseJson } from "../../../lib/measurekit/json.ts"

export const GENERATED_CLAUDE_MD_HEADER =
  "<!-- GENERATED by keel bin/link from PRINCIPLES.md + PERSONAL.md. " +
  "Edit the sources, then run bin/link --write. -->"
const V1_BASELINE_SUFFIX = "-v1baseline"
const PROJECT_SLUG_CHARS = /[^A-Za-z0-9]/gu
const KEEL_PLUGIN_ID = "keel@keel"

export interface ConfigFingerprint {
  link_mode: LinkMode
  claude_md_sha256: string | null
  principles_md_sha256: string | null
  skill_md_sha256: string | null
}

export const CONFIG_FINGERPRINT_KEYS = ["link_mode", "claude_md_sha256", "principles_md_sha256", "skill_md_sha256"] as const satisfies readonly (keyof ConfigFingerprint)[]

export function cliConfigDir(): string {
  return process.env["CLAUDE_CONFIG_DIR"] || expandHome("~/.claude")
}

export function isKeelLive(configDir: string, keelHome: string, skill: string): boolean {
  if (linkMode(configDir, keelHome) === "plugin") {
    return isKeelPluginEnabled(configDir) && isFile(pluginSkillFile(keelHome, skill)) && isFile(principlesFile(keelHome))
  }
  const skillLink = path.join(configDir, "skills", skill)
  return linksInto(skillLink, keelHome) && isGenerated(path.join(configDir, "CLAUDE.md"))
}

function linkMode(configDir: string, keelHome: string): LinkMode {
  return readRecordedMode({ keelHome, overlayDir: env.overlayDir(), dataDir: configDir })
}

export function suiteEvalId(evalId: string, keelLive: boolean): string {
  return keelLive ? evalId : evalId + V1_BASELINE_SUFFIX
}

export function configFingerprint(configDir: string, keelHome: string, skill: string): ConfigFingerprint {
  const mode = linkMode(configDir, keelHome)
  const pluginServes = mode === "plugin"
  return {
    link_mode: mode,
    claude_md_sha256: sha256(path.join(configDir, "CLAUDE.md")),
    principles_md_sha256: pluginServes ? sha256(principlesFile(keelHome)) : null,
    skill_md_sha256: sha256(pluginServes ? pluginSkillFile(keelHome, skill) : path.join(configDir, "skills", skill, "SKILL.md")),
  }
}

export function projectDirFor(cwd: string, configDir: string): string {
  return path.join(configDir, "projects", resolveLinks(cwd).replace(PROJECT_SLUG_CHARS, "-"))
}

function isKeelPluginEnabled(configDir: string): boolean {
  const settingsFile = path.join(configDir, "settings.json")
  if (!isFile(settingsFile)) return false
  const settings = parseJson(readUtf8(settingsFile))
  const enabledPlugins = isJsonObject(settings) ? settings["enabledPlugins"] : undefined
  return isJsonObject(enabledPlugins) && enabledPlugins[KEEL_PLUGIN_ID] === true
}

function pluginSkillFile(keelHome: string, skill: string): string {
  return path.join(keelHome, "skills", skill, "SKILL.md")
}

function principlesFile(keelHome: string): string {
  return path.join(keelHome, "PRINCIPLES.md")
}

function linksInto(link: string, root: string): boolean {
  if (!isSymlink(link)) return false
  const pointee = resolveLinks(link)
  const realRoot = resolveLinks(root)
  return pointee === realRoot || pointee.startsWith(realRoot + "/")
}

function isGenerated(file: string): boolean {
  if (isSymlink(file) || !isFile(file)) return false
  return firstLine(file) === GENERATED_CLAUDE_MD_HEADER
}

function sha256(file: string): string | null {
  if (!isFile(file)) return null
  return createHash("sha256").update(fs.readFileSync(file)).digest("hex")
}
